style.css:
@-moz-document domain("bilibili.tv") {
/* Mainpage*/
	/*color: var(--text-light) !important; white gray*/
	/*color: var(--text-gray) !important; gray*/
	/*color: var(--text-white) !important; White */
	/*background-color: rgb(32, 33, 36) !important; * black/
	/* color: var(--main-bg); black*/
	/* background-color: var(--main-bg) !important;*/
	/*background: var(--accent-pink) !important; Pink*/
	/*color: var(--accent-pink) !important; Pink*/
	/*color: var(--accent-blue) !important; Blue*/

	:root {
		--main-bg: #202124;
		--secondary-bg: #333;
		--text-white: #fff;
		--text-light: #eee;
		--text-gray: #bdc1c6;
		--text-dark: #202124;
		--accent-pink: #f26e91;
		--accent-blue: #4c93ff;
		--accent-red: #ff4747;
		--tag-lightblue: #06b6f2;
	}

	/* LOGIN */
	.info-tip__text {
		font-size: 14px;
		line-height: 18px;
		font-weight: 800px;
		color: var(--accent-pink) !important;
	}

	.info-tip__icon {
		font-size: 24px;
		width: 24px;
		height: 24px;
		line-height: 24px;
		color: var(--accent-pink) !important;
	}

	.dialog__container {
		background: var(--main-bg) !important;
	}

	.dialog__header>span {
		color: var(--text-light) !important;
	}

	.popover,
	.bstar-header-login-panel {
		background: var(--main-bg) !important;
	}

	.login-tip {
		color: var(--text-light) !important;
	}

	/* END LOGIN */
	/* HomePage*/
	/* history */
	.bstar-header-search-history__item {
		background: rgba(0, 0, 0, .55) !important;
	}

	.bstar-header-search-history__text {
		color: var(--accent-pink) !important;
	}

	.bstar-header-search-history__btn {
		color: var(--accent-red) !important;
	}

	/* end history */
	.element.style {
		background: var(--main-bg) !important;
	}

	p {
		color: var(--text-white) !important;
	}

	h1,
	h2,
	h3 {
		color: var(--text-light) !important;
	}

	h5 {
		color: var(--text-dark) !important;
	}

	.bstar-header__download-content-header,
	.bstar-header__download-content-qrcode--desc {
		color: var(--text-dark) !important;
	}

	/*
	element.style 
	{
		background-color: var(--main-bg) !important;
	}
	*/
	.bstar-header__left-menu[data-v-b46c0254]:not(.transparent) {
		color: var(--text-white) !important;
	}

	.bstar-header__left-logo,
	.bstar-sidebar__logo {
		display: block;
		-moz-box-sizing: border-box;
		box-sizing: border-box;
		background: url(data:image/png;base64,) no-repeat;
		width: 202px;
		/* Width of new image */
		height: 34px;
		/* Height of new image */
		padding-left: 0px;
		/* Equal to width of new image */
		padding-top: 25px;
	}

	.colour-icon-bilibili-logo:before {
		content: url(data:image/png;base64,) !important;
	}

	::placeholder {
		color: var(--text-gray);
	}

	.loading {
		color: var(--text-white) !important;
	}

	body {
		background-color: rgb(255, 255, 255) !important;
		font-size: 14px !important;
		color: var(--text-white) !important;
	}

	.bstar-video-card__nickname {
		color: var(--accent-pink) !important;
	}

	.card-text__tag {
		color: var(--accent-pink) !important;
	}

	/* scroll-container__content */
	.scroll-container__item {
		font-size: 14px !important;
		color: var(--text-light) !important;
	}

	.scroll-container__item--active {
		font-size: 14px !important;
		color: var(--accent-pink) !important;
	}

	.scroll-container__item--bold {
		font-size: 14px !important;
		color: var(--accent-blue) !important;
	}

	/* end scroll-container__content */
	/* media */
	.detail-operate__desc>p,
	.detail-table__label {
		color: var(--text-white) !important;
	}

	.detail-table__text {
		color: var(--text-gray) !important;
	}

	.breadcrumb__item-text {
		color: var(--accent-pink) !important;
	}

	/* end media*/
	/* download icon*/
	.bstar-header__download-btn {
		color: var(--text-light) !important;
	}

	.bstar-header__download-btn.transparent {
		background-color: unset !important;
	}

	.bstar-header__download-btn:before {
		background-image: url(data:image/svg+xml;base64,) !important;
	}

	/* end download icon*/
	.bstar-header__fastcharge-btn:not(.transparent) {
		color: var(--text-white) !important;
		background-color: rgba(0, 0, 0, .05);
	}

	/* payments */
	.bstar-header-search-bar:not(.transparent) .bstar-header-search-bar__btn button {
		color: var(--text-light) !important;
	}

	/* end pymets*/
	.bstar-header__action:not(.transparent) {
		color: var(--text-light) !important;
	}

	.bstar-header__left-menu[data-v-65886838]:not(.transparent) {
		color: var(--text-light) !important;
	}

	.bstar-header-search-suggest__item--icon[data-v-6175f9a6] {
		font-size: 16px;
		width: 16px;
		height: 16px;
		color: var(--text-light) !important;
		margin-right: 8px;
	}

	.bstar-sidebar__menu {
		color: var(--text-light) !important;
	}

	.vip-notification {
		background-color: var(--accent-pink) !important;
	}

	.bstar-tab--largeLine .bstar-tab__item.active:after {
		background-color: var(--accent-pink) !important;
	}

	/*End HomePage*/
	/* Anime PAGE */
	.anime {
		background: var(--main-bg) !important;
	}

	.anime {
		background: var(--main-bg) !important;
	}

	.calendar-time .recent-updates {
		color: var(--text-light) !important;
	}

	.card-section-content .card-play .card-play-icon {
		color: var(--accent-pink) !important;
	}

	.card-section .card-bottom .card-title,
	.card-section .card-bottom .card-time,
	.calendar .calendar-content .card-title {
		color: var(--text-light) !important;
	}

	.calendar-time .recent-time {
		color: var(--accent-pink) !important;
	}

	.calendar-time .recent-time.today:after {
		background-color: var(--accent-red) !important;
	}

	.calendar-time .recent-updates.active {
		background-color: var(--accent-pink) !important;
	}

	.calendar .calendar-content .calendar-scroll-line {
		border-color: var(--accent-pink) !important;
	}

	.area-title .view-all {
		color: var(--accent-pink) !important;
	}

	/* END Anime PAGE */
	.anime-timeline:not(.anime-timeline--mobile) .anime-timeline__subtitle {
		position: unset !important;
	}

	/* Flying Coment*/
	input {
		color: var(--text-white) !important;
	}

	.bstar-danmaku__icon {
		background-color: var(--text-white) !important;
		border-radius: 8px !important;
	}

	/* END Flying Coment*/
	/* premium  https://www.bilibili.tv/vip/th/purchase */
	.vip-product-entity__content>h4 {
		color: var(--text-white) !important;
	}

	.bstar-header__benefits-popover {
		background: var(--text-white) !important;
	}

	.bstar-header__benefits-popover__top-desc,
	.bstar-header__benefits-popover__list-desc,
	.benefit-tips__item>span,
	.vip-products__tips {
		color: var(--text-white) !important;
	}

	.vip>main {
		background: var(--secondary-bg) !important;
	}

	.vip-payment-entity__name-text,
	.vip-payments__header>a {
		color: var(--accent-pink) !important;
	}

	.benefits__title {
		color: var(--accent-pink) !important;
	}

	.vip-benefits__title--right {
		color: var(--accent-pink) !important;
	}

	.vip-benefits__item-icon {
		color: var(--accent-pink) !important;
	}

	.vip>main .vip__footer {
		background: var(--secondary-bg) !important;
	}

	.vip-product-entity__introduction {
		color: var(--text-white) !important;
	}

	.vip-product-entity__desc {
		color: #ff4a80 !important;
	}

	/* END premium */
	/* redeem https://www.bilibili.tv/vip/th/redeem */
	.bstar-vip-info>span {
		color: var(--text-light) !important;
	}

	.bstar-redeem-box {
		background-color: var(--secondary-bg) !important;
	}

	.bstar-form-item__label {
		color: var(--text-white) !important;
	}

	.bstar-input__inner {
		background-color: var(--secondary-bg) !important;
		;
	}

	/* END redeem https://www.bilibili.tv/vip/th/redeem */
	.space-info__count,
	.space-info__count__item {
		color: var(--text-light) !important;
	}

	.bstar-header-user-content__name {
		color: var(--main-bg) !important;
	}

	.bstar-tab__item.active,
	.bstar-tab--large .bstar-tab__item.active {
		color: var(--accent-pink) !important;
	}

	/* history__ */
	.creator-card {
		background-color: var(--accent-pink) !important;
	}

	.creator-card__num {
		color: var(--text-white) !important;
	}

	.bstar-button--hollow.bstar-button--color-default {
		color: var(--text-light) !important;
		border: 1px solid var(--text-light) !important;
	}

	.more-action__container {
		background: var(--accent-blue) !important;
	}

	.history__header,
	.fav__header {
		background-color: var(--main-bg) !important;
	}

	.bstar-header__popover-body,
	.bstar-header__popover-list,
	.bstar-header__popover-all {
		background-color: var(--main-bg) !important;
	}

	.bstar-header__history-title,
	.bstar-header__popover-all {
		color: var(--text-light) !important;
	}

	.bstar-header-search-history__title,
	.bstar-header-search-bar.transparent .bstar-header-search-bar__btn button,
	.bstar-header .transparent .sic-bstar-upload_nav,
	.bstar-header .transparent .sic-bstar-history_nav,
	.bstar-header .transparent .sic-bstar-mylist_nav,
	.bstar-header .transparent .sic-bstar-search,
	.bstar-header .transparent .sic-bstar-more_nav,
	.bstar-header .transparent .sic-bstar-expand,
	.bstar-header__left-menu:not(.transparent) {
		color: var(--text-light) !important;
	}

	.category-title__more {
		color: var(--text-white) !important;
	}

	.search-result__tabs--sticky {
		background-color: var(--main-bg) !important;
	}

	.highlights__text {
		color: var(--text-light) !important;
	}

	/* end history__ */
	/* Bar */

	/*.bstar-header, .bstar-web__header.bstar-web__header-white , .header.header, .interactive, .bstar-header-search-bar{
    	background-color: rgb(32, 33, 36) !important;
	}*/
	.interactive {
		background-color: rgb(32, 33, 36) !important;
	}

	.bstar-header:not(.transparent) {
		background-color: rgb(32, 33, 36) !important;
	}

	.bstar-header {
		background-color: transparent;
	}

	.bstar-header-search-bar.transparent {
		background-color: rgba(35, 35, 35, 0.075) !important;
	}

	.bstar-video-card__tag {
		color: var(--accent-pink) !important;
	}

	.bstar-video-tag,
	.bstar-meta__anime-tag {
		color: var(--accent-blue) !important;
		background-color: rgb(0, 0, 0) !important;
	}

	.bstar-video-card__title-text,
	.bstar-tab__item {
		color: var(--text-white) !important;
	}

	.bstar-video-card__desc,
	.bstar-video-card__view-at,
	.bstar-video-card__view {
		color: var(--text-light) !important;
	}

	.bstar-header {
		border-bottom: 1px solid var(--main-bg) !important;
	}

	/* short-drama page*/

	.short_drama {
		background: var(--main-bg) !important;
	}

	.bstar-meta-tag--short-drama {
		color: var(--tag-lightblue) !important;
		background-color: rgba(6, 182, 242, .2) !important;
	}

	.card-section .card-lucency {
		border-style: groove !important;
		border-color: var(--accent-pink) !important;
		box-shadow: 1px 1px 20px 0px var(--accent-pink) !important;
		border-radius: 10px !important;
	}

	.card-section .card-lucency .card-overlay .card-overlay-top {
		flex: 1;
		background: linear-gradient(180deg, rgba(34, 34, 34, 0) 0%, rgba(34, 34, 34, .7) 50%, rgba(242, 97, 131, .3) 100%) !important;
	}


	/* end short-drama page*/


	/* Footer */
	.bstar-sidebar__footer {
		border-top: 1px solid var(--main-bg) !important;
		color: var(--text-light) !important;
	}

	/*.bstar-sidebar__footer::after
	{
		content:"bilibili.tv mystylish Dark Theme";
	} */
	.bstar-sidebar__footer>span {
		display: block;
		margin-top: 4px;
		font-size: 12px;
		color: var(--text-light) !important;
	}

	.footer__container .footer__item {
		color: var(--text-gray) !important;
	}

	/* END Footer */
	.sidebar__link {
		color: var(--text-gray) !important;
	}

	.bstar-header-search-bar__input {
		color: var(--text-light) !important;
		background-color: var(--accent-pink) !important;
		border-radius: 15px 50px 30px 5px;
	}

	.bstar-header-search-top-card__title {
		color: var(--text-light) !important;
	}

	.breadcrumb__item {
		color: var(--text-white) !important;
	}

	.section-bar__item:not(.section-bar__item--mobile).active {
		color: var(--accent-pink) !important;
	}

	.section-bar__item {
		color: var(--text-white) !important;
	}

	.warn-tip__text {
		color: #ff8282 !important;
	}

	/*- comment */
	.comment__name h5 {
		color: var(--accent-pink) !important;
	}

	.comment-wrap__total {
		color: var(--text-gray) !important;
	}

	.comment-send__textarea {
		background-color: #000000 !important;
	}

	.comment-send__textarea__inner>textarea,
	.comment-send__textarea__inner::after,
	.comment-send__textarea__inner {
		color: var(--text-white) !important;
		border-radius: 20px !important;
		font-weight: bold !important;
		;
	}

	.comment-send__btn {
		color: var(--accent-pink) !important;
	}

	.comment-wrap__send--bottom {
		background-color: rgba(28, 28, 28, 0.90) !important;
		border-radius: 20px !important;
	}

	.children-comment-list__operate-item {
		color: var(--text-light) !important;
	}

	.comment__translation {
		color: var(--accent-blue) !important;
	}

	.comment__tag.creator-like {
		color: var(--tag-lightblue) !important;
	}

	/*- end comment */
	/* category__container */
	.category__container {
		background-color: var(--main-bg) !important;
	}

	.category__title,
	.category__item {
		color: var(--text-white) !important;
	}

	/* end category__container */
	/* Time line https://www.bilibili.tv/th/timeline */
	.timeline {
		background: var(--main-bg) !important;
	}

	.timeline-header--today {
		border: 2px solid var(--accent-pink) !important;
		background-image: linear-gradient(345deg, #FF81E000 0%, var(--accent-pink) 100%) !important;
	}

	.timeline__weeks__item .item-week,
	.timeline__weeks__item.active .item-date,
	.timeline__weeks__item.active .item-week {
		color: var(--text-white) !important;
	}

	.timeline__weeks__item.active {
		background: var(--accent-pink) !important;
	}

	.timeline-tab__item {
		color: var(--text-white) !important;
