		color: var(--text-light) !important;
	}

	.bstar-meta {
		color: var(--text-gray) !important;
	}

	.ep-item__reference {
		/**color: var(--text-gray) !important;**/
		color: var(--accent-pink) !important;
	}

	.ep-item__reference--active,
	.ep-item__reference--active:hover {
		background-color: var(--accent-pink)33 !important;
	}

	.card-text__title {
		color: var(--text-gray) !important;
	}

	.li,
	.span,
