	.section-bar__item:not(.section-bar__item--mobile).active:after {
		background-color: #f26183 !important;
	}

	.ep-item {
		color: var(--text-white) !important;
		border: #f26183;
		border-style: inset;
		box-shadow: 1px 1px 1px 0px var(--accent-pink) !important;
		border-radius: 10px !important;
		border-width: 1px;
	}

	.coming-soon {
		background-color: var(--secondary-bg) !important;
	}

