	@font-face {
		font-family: 'Arial';
		font-style: normal;
		font-weight: 600;
		font-display: swap;
		src: url(https://fonts.gstatic.com/s/mali/v13/N0bV2SRONuN4QN7nGlNQJA.woff2) format('woff2');
